{"content":"import time
from collections import OrderedDict


class LRUCache:
    """Least-recently-used cache whose entries also expire after a TTL.

    Entries are stored in an OrderedDict in order of use (oldest first).
    Each value is paired with its absolute expiry time (None if ttl is None).
    """

    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)

    def _expired(self, entry, now):
        expires_at = entry[1]
        return expires_at is not None and now >= expires_at

    def _purge_expired(self, now):
        for key in [k for k, e in self._data.items() if self._expired(e, now)]:
            del self._data[key]

    def get(self, key, default=None):
        now = self.clock()
        try:
            entry = self._data[key]
        except KeyError:
            return default
        if self._expired(entry, now):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return entry[0]

    def put(self, key, value):
        now = self.clock()
        self._purge_expired(now)
        expires_at = None if self.ttl is None else now + self.ttl
        self._data[key] = (value, expires_at)
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        now = self.clock()
        return sum(1 for e in self._data.values() if not self._expired(e, now))

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        return not self._expired(entry, self.clock())
